import { useEffect, useRef } from 'react';
import manifest from '../data/video-manifest.json';
import { imageUrl } from '../lib/paths';

const stem = (src) => src.replace(/\.[^.]+$/, '');

// A short silent looping video (generated by `npm run videos`), used in place
// of a GIF. It only plays while on screen, and for visitors who prefer reduced
// motion it stays on the poster frame with play controls instead.
export default function Clip({ src, alt }) {
  const ref = useRef(null);
  const info = manifest[src];
  if (!info) throw new Error(`Clip "${src}" is not in video-manifest.json — run npm run videos`);

  useEffect(() => {
    const video = ref.current;
    video.muted = true; // React doesn't reliably set the muted attribute, and autoplay requires it
    if (window.matchMedia?.('(prefers-reduced-motion: reduce)').matches) {
      video.controls = true;
      return undefined;
    }
    if (!('IntersectionObserver' in window)) {
      video.play().catch(() => {});
      return undefined;
    }
    const observer = new IntersectionObserver(([entry]) => {
      if (entry.isIntersecting) video.play().catch(() => {});
      else video.pause();
    }, { threshold: 0.25 });
    observer.observe(video);
    return () => observer.disconnect();
  }, []);

  return (
    <video
      ref={ref}
      poster={imageUrl(`${stem(src)}-poster.jpg`)}
      width={info.width}
      height={info.height}
      aria-label={alt}
      preload="none"
      muted
      loop
      playsInline
    >
      <source src={imageUrl(`${stem(src)}.mp4`)} type="video/mp4" />
    </video>
  );
}

export const clipRatio = (src) => {
  const info = manifest[src];
  return info ? info.width / info.height : 1;
};
